const params=new URLSearchParams(location.search);const applyInfolensTheme=(theme)=>document.documentElement.dataset.theme=theme==="dark"?"dark":"light";applyInfolensTheme(params.get("theme"));addEventListener("message",(event)=>{if(event.data?.type==="infolens:theme")applyInfolensTheme(event.data.theme)});const api=params.get("apiBaseUrl")||"../api/";const root=document.querySelector("#app");let data;let refreshing=false;let settingsOpen=false;
const icons={refresh:'<svg viewBox="0 0 24 24"><path d="M20 12a8 8 0 1 1-2.3-5.7L20 8"/><path d="M20 3v5h-5"/></svg>',settings:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3"/><path d="M19 15a2 2 0 0 0 .4 2l-2.4 2.4a2 2 0 0 0-2-.4 2 2 0 0 0-1 2h-4a2 2 0 0 0-1-2 2 2 0 0 0-2 .4L4.6 17A2 2 0 0 0 5 15a2 2 0 0 0-2-1v-4a2 2 0 0 0 2-1 2 2 0 0 0-.4-2L7 4.6A2 2 0 0 0 9 5a2 2 0 0 0 1-2h4a2 2 0 0 0 1 2 2 2 0 0 0 2-.4L19.4 7A2 2 0 0 0 19 9a2 2 0 0 0 2 1v4a2 2 0 0 0-2 1Z"/></svg>'};
async function request(route,method="GET"){const response=await fetch(`${api}${route}`,{method});if(!response.ok)throw new Error("知乎热榜服务暂时不可用");return response.json()}
function escape(value){const node=document.createElement("span");node.textContent=value??"";return node.innerHTML}
function formatTime(value){return value?`更新于 ${new Date(value).toLocaleString("zh-CN",{month:"numeric",day:"numeric",hour:"2-digit",minute:"2-digit"})}`:"尚未刷新"}
function header(){return`<header class="workspace-header"><div class="workspace-title"><span class="source-mark">知</span><div><h1>知乎热榜</h1><span class="refresh-time">${formatTime(data?.lastSuccessfulRefresh)}</span></div></div><div class="header-actions"><button class="icon-button ${refreshing?"spinning":""}" id="refresh" aria-label="刷新" title="刷新" ${data?.settings?.policy==="disabled"?"disabled":""}>${icons.refresh}</button><button class="icon-button" id="settings" aria-label="刷新设置" title="刷新设置">${icons.settings}</button></div></header>`}
function dependency(){const disconnected=data.dependencyState==="disconnected";return`<section class="dependency"><div class="dependency-icon">${disconnected?"桥":"知"}</div><h2>${disconnected?"浏览器连接不可用":"需要重新登录知乎"}</h2><p>${disconnected?"知乎热榜需要已连接的 Browser Bridge。其他信息源不受影响。":"Browser Bridge 已连接，但当前知乎会话已过期。请在 Chrome 中登录知乎后重试。"}</p><div class="dependency-actions"><button class="primary" id="retry">检查连接</button><button class="secondary" id="recover">${disconnected?"安装 Browser Bridge":"打开知乎"}</button></div></section>`}
function content(){if(!data.questions.length)return`<section class="empty"><h2>还没有保留的热榜</h2><p>首次刷新会通过当前 Chrome 登录会话读取知乎热榜。</p><button class="primary" id="empty-refresh">刷新热榜</button></section>`;return`<ol class="question-list">${data.questions.map(item=>`<li class="question-row ${item.read?"is-read":""}" data-url="${escape(item.url)}" tabindex="0"><span class="rank ${item.rank<=3?"top":""}">${item.rank}</span><div><h2>${escape(item.title)}</h2>${item.excerpt?`<p>${escape(item.excerpt)}</p>`:""}</div><div class="metrics"><strong>${escape(item.heat)}</strong><span>${item.answers} 个回答</span></div></li>`).join("")}</ol>`}
function warning(){return data.lastError&&data.dependencyState==="connected"?`<div class="warning" role="alert"><span>刷新失败，正在显示上次保留的内容。</span><button id="warning-retry">重试</button></div>`:""}
function sheet(){if(!settingsOpen)return"";const s=data.settings;return`<div class="scrim" id="scrim"></div><aside class="sheet" role="dialog" aria-modal="true" aria-labelledby="settings-title"><header><h2 id="settings-title">刷新设置</h2><button class="icon-button" id="close" aria-label="关闭">×</button></header><form id="settings-form"><label><input type="radio" name="policy" value="manual" ${s.policy==="manual"?"checked":""}>仅手动刷新</label><label><input type="radio" name="policy" value="disabled" ${s.policy==="disabled"?"checked":""}>停用刷新</label><label><input type="radio" name="policy" value="fixed" ${s.policy==="fixed"?"checked":""}>固定间隔</label><select name="intervalMinutes" aria-label="刷新间隔"><option value="60">每小时</option><option value="360">每 6 小时</option><option value="720">每 12 小时</option><option value="1440">每天</option></select><div class="sheet-actions"><button class="secondary" type="button" id="cancel">取消</button><button class="primary" type="submit">保存</button></div></form></aside>`}
function render(){root.innerHTML=header()+warning()+(["disconnected","login-required"].includes(data?.dependencyState)?dependency():content())+sheet();bind()}
async function refresh(){if(refreshing)return;refreshing=true;render();try{await request("refresh","POST");data=await request("summary")}catch(error){const latest=await request("summary").catch(()=>data);data={...latest,lastError:latest?.lastError??error.message}}finally{refreshing=false;render()}}
function bind(){document.querySelector("#refresh")?.addEventListener("click",refresh);for(const id of["retry","empty-refresh","warning-retry"])document.querySelector(`#${id}`)?.addEventListener("click",refresh);document.querySelector("#settings")?.addEventListener("click",()=>{settingsOpen=true;render();document.querySelector('input[name="policy"]:checked')?.focus()});for(const id of["close","cancel","scrim"])document.querySelector(`#${id}`)?.addEventListener("click",()=>{settingsOpen=false;render();document.querySelector("#settings")?.focus()});document.querySelector("#recover")?.addEventListener("click",()=>window.open(data.dependencyState==="disconnected"?"https://chromewebstore.google.com/detail/opencli/ildkmabpimmkaediidaifkhjpohdnifk":"https://www.zhihu.com/","_blank","noopener"));document.querySelectorAll(".question-row").forEach(row=>{const open=async()=>{await request(`read?url=${encodeURIComponent(row.dataset.url)}`,"POST");window.open(row.dataset.url,"_blank","noopener");data=await request("summary");render()};row.addEventListener("click",open);row.addEventListener("keydown",event=>{if(event.key==="Enter")open()})});document.querySelector("#settings-form")?.addEventListener("submit",async event=>{event.preventDefault();const form=new FormData(event.currentTarget);data.settings=await request(`settings?policy=${encodeURIComponent(form.get("policy"))}&intervalMinutes=${encodeURIComponent(form.get("intervalMinutes"))}`,"POST");settingsOpen=false;render()});const interval=document.querySelector('[name="intervalMinutes"]');if(interval)interval.value=String(data.settings.intervalMinutes)}
document.addEventListener("keydown",event=>{if(event.key==="Escape"&&settingsOpen){settingsOpen=false;render()}});request("summary").then(value=>{data=value;render()}).catch(error=>{root.innerHTML=`<div class="loading">${escape(error.message)}</div>`});
